class Solution {
public:
    long long countSubarrays(vector<int>& nums, long long k) {
        long long ans = 0, sum = 0;
        int left = 0;
        int n = (int)nums.size();
        for (int right = 0; right < n; right++) {
            sum += nums[right];
            while (sum * (long long)(right - left + 1) >= k) {
                sum -= nums[left];
                left++;
            }
            ans += (long long)(right - left + 1);
        }
        return ans;
    }
};
